#include <stdio.h>
#include <stdlib.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    int idx = 0;
    for (int i = 0; i < n; i++) if (a[i] != 0) a[idx++] = a[i];
    while (idx < n) a[idx++] = 0;
    for (int i = 0; i < n; i++) {
        if (i > 0) putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');
    free(a);
    return 0;
}

