code.JavaScript:
const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/).map(Number);
    if (toks.length > 0) {
        const n = toks[0];
        const arr = toks.slice(1, 1 + n);
        const nz = arr.filter(x => x !== 0);
        const zeros = new Array(n - nz.length).fill(0);
        console.log(nz.concat(zeros).join(" "));
    }
}
main();

